import{_ as a,o as e,c as o,a5 as n}from"./chunks/framework.Bt0SrEfo.js";const u=JSON.parse('{"title":"项目开篇","description":"","frontmatter":{},"headers":[],"relativePath":"面试/项目/index.md","filePath":"面试/项目/index.md","lastUpdated":1791733354000}'),r={name:"面试/项目/index.md"};function l(s,t,i,d,p,c){return e(),o("div",null,[...t[0]||(t[0]=[n(`<h1 id="项目开篇" tabindex="-1">项目开篇 <a class="header-anchor" href="#项目开篇" aria-label="Permalink to &quot;项目开篇&quot;">​</a></h1><blockquote><p>面试通过项目名问问题，核心是<strong>项目场景、亮点、概率 + 经验反推</strong>，而不是&quot;背简历项目名&quot;。</p></blockquote><h2 id="项目相关问题" tabindex="-1">项目相关问题 <a class="header-anchor" href="#项目相关问题" aria-label="Permalink to &quot;项目相关问题&quot;">​</a></h2><h3 id="为什么-webpack-4-→-webpack-5-升级" tabindex="-1">为什么 webpack 4 → webpack 5 升级？ <a class="header-anchor" href="#为什么-webpack-4-→-webpack-5-升级" aria-label="Permalink to &quot;为什么 webpack 4 → webpack 5 升级？&quot;">​</a></h3><blockquote><p>简历中能体现升级能力。</p></blockquote><ul><li><strong>构建速度</strong>：Webpack5 用持久化缓存（filesystem cache），二次构建提速 60-90%。</li><li><strong>产物优化</strong>：开箱即用的 Tree Shaking、副作用分析，比 Webpack4 更准确。</li><li><strong>Module Federation</strong>：微前端/跨应用共享模块。</li><li><strong>长期支持</strong>：Webpack4 已停止维护，部分 loader/plugin 已不兼容。</li></ul><h3 id="webpack-5-模块联邦-module-federation" tabindex="-1">Webpack 5 模块联邦（Module Federation） <a class="header-anchor" href="#webpack-5-模块联邦-module-federation" aria-label="Permalink to &quot;Webpack 5 模块联邦（Module Federation）&quot;">​</a></h3><ul><li><strong>是什么</strong>：让多个独立构建的应用<strong>运行时共享模块</strong>，实现微前端或组件库复用。</li><li><strong>怎么用</strong>： <ul><li>容器应用：<code>exposes</code> 暴露模块，<code>remotes</code> 消费远程模块</li><li>被消费应用：<code>filename</code> 决定远端入口</li></ul></li><li><strong>典型场景</strong>：跨应用共享设计系统组件、公共业务组件。</li></ul><h3 id="项目中-node-端服务-做了什么" tabindex="-1">项目中&quot;Node 端服务&quot;做了什么？ <a class="header-anchor" href="#项目中-node-端服务-做了什么" aria-label="Permalink to &quot;项目中&quot;Node 端服务&quot;做了什么？&quot;">​</a></h3><ul><li>SSR 渲染（Next.js / Nuxt 的 Node runtime）</li><li>BFF 层聚合接口（聚合多个后端接口、裁剪字段、加缓存）</li><li>中间层做用户鉴权 / 灰度 / AB Test</li></ul><h3 id="性能优化常见举例" tabindex="-1">性能优化常见举例 <a class="header-anchor" href="#性能优化常见举例" aria-label="Permalink to &quot;性能优化常见举例&quot;">​</a></h3><ul><li><strong>构建体积</strong>：terser/swc 压缩、SplitChunks 拆包、按需引入（babel-plugin-import）、CDN + externals</li><li><strong>运行时</strong>：路由懒加载、组件 lazy + Suspense、图片 lazyload + WebP、骨架屏 + SSR</li><li><strong>网络</strong>：HTTP/2（多路复用 + header 压缩）、gzip/brotli、强缓存（Cache-Control + hash）、预加载（preload/prefetch）</li><li><strong>渲染</strong>：避免回流重绘（transform/opacity）、CSS contain、长列表虚拟滚动</li></ul><h3 id="项目里最有挑战的事" tabindex="-1">项目里最有挑战的事？ <a class="header-anchor" href="#项目里最有挑战的事" aria-label="Permalink to &quot;项目里最有挑战的事？&quot;">​</a></h3><blockquote><p>按 STAR 法则准备 1-2 个：</p></blockquote><ul><li><strong>S</strong>ituation：业务场景 / 复杂度 / 规模</li><li><strong>T</strong>ask：你的职责 / 难点</li><li><strong>A</strong>ction：技术方案 / 选型 / 关键决策</li><li><strong>R</strong>esult：数据化产出（启动时间、转化率、人效）</li></ul><p>→ 参考 <a href="/面试/3-自我介绍#六面试官听完自我介绍后的高频追问">自我介绍 §6 STAR</a></p><h3 id="描述你解决复杂技术问题的流程" tabindex="-1">描述你解决复杂技术问题的流程？ <a class="header-anchor" href="#描述你解决复杂技术问题的流程" aria-label="Permalink to &quot;描述你解决复杂技术问题的流程？&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 问题定义（输入输出、错误现象、影响面）</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>2. 复现路径（最小用例、调试工具、断点）</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>3. 假设 + 验证（控制变量 + 排查假设）</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>4. 临时方案 + 长期方案（止血 + 根治）</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>5. 复盘 + 文档化（沉淀到团队知识库）</span></span></code></pre></div><h3 id="团队中如何交流这些问题" tabindex="-1">团队中如何交流这些问题？ <a class="header-anchor" href="#团队中如何交流这些问题" aria-label="Permalink to &quot;团队中如何交流这些问题？&quot;">​</a></h3><ul><li><strong>轻决策</strong>：拉个 15 分钟会 + 画图 / 推 demo</li><li><strong>重决策</strong>：写 RFC / Tech Proposal，同步给上下游</li><li><strong>跨团队</strong>：开会同步 + 会后书面跟进</li><li><strong>线上事故</strong>：建立事故时间线，事后做 Postmortem</li></ul><h2 id="vite-与-webpack-的区别" tabindex="-1">Vite 与 Webpack 的区别 <a class="header-anchor" href="#vite-与-webpack-的区别" aria-label="Permalink to &quot;Vite 与 Webpack 的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>Webpack</th><th>Vite</th></tr></thead><tbody><tr><td>dev 模型</td><td>全量打包 + dev server</td><td>浏览器原生 ESM + 按需编译</td></tr><tr><td>冷启动</td><td>模块越多越慢</td><td>几乎与模块数无关</td></tr><tr><td>HMR</td><td>2-3s（受 bundle 大小影响）</td><td>&lt; 50ms</td></tr><tr><td>生产构建</td><td>Webpack</td><td>Rollup（Vite 借用）</td></tr><tr><td>生态</td><td>极其成熟</td><td>新项目首选</td></tr><tr><td>适用场景</td><td>微前端 MF、复杂定制</td><td>新项目、追求开发体验</td></tr></tbody></table><blockquote><p>📚 详细对比：<a href="/工程化/vite/2-why-fast">Vite 为什么快</a> · <a href="/工程化/vite/8-vs-webpack">Vite vs Webpack</a></p></blockquote><h2 id="pnpm-yarn-npm-monorepo" tabindex="-1">pnpm / yarn / npm + monorepo <a class="header-anchor" href="#pnpm-yarn-npm-monorepo" aria-label="Permalink to &quot;pnpm / yarn / npm + monorepo&quot;">​</a></h2><h3 id="npm-yarn-的问题" tabindex="-1">npm/yarn 的问题 <a class="header-anchor" href="#npm-yarn-的问题" aria-label="Permalink to &quot;npm/yarn 的问题&quot;">​</a></h3><ul><li><strong>性能差</strong>：必须遍历所有项目依赖构建完整关系树。</li><li><strong>缓存弱</strong>：重复下载依赖、磁盘浪费。</li><li><strong>幽灵依赖</strong>：依赖提升导致 <code>import &#39;未声明的包&#39;</code> 不报错，切换包管理器后炸。</li></ul><h3 id="pnpm-优势" tabindex="-1">pnpm 优势 <a class="header-anchor" href="#pnpm-优势" aria-label="Permalink to &quot;pnpm 优势&quot;">​</a></h3><ul><li><strong>硬链接 + 内容寻址存储</strong>：磁盘节省 50%+，安装速度提升 2-3x。</li><li><strong>非平铺 node_modules</strong>：杜绝幽灵依赖。</li><li><strong>monorepo 原生</strong>：workspaces 配置简洁。</li></ul><h3 id="monorepo-实践" tabindex="-1">monorepo 实践 <a class="header-anchor" href="#monorepo-实践" aria-label="Permalink to &quot;monorepo 实践&quot;">​</a></h3><ul><li><strong>目录结构</strong>：<code>packages/app</code>、<code>packages/ui</code>、<code>packages/utils</code></li><li><strong>工具选型</strong>： <ul><li>轻量：pnpm workspaces</li><li>中量：Turborepo（任务编排 + 缓存）</li><li>重量：Nx（依赖图 + 代码生成）</li></ul></li></ul><h2 id="提问环节-面试反问" tabindex="-1">提问环节（面试反问） <a class="header-anchor" href="#提问环节-面试反问" aria-label="Permalink to &quot;提问环节（面试反问）&quot;">​</a></h2><p>面试结束面试官会问&quot;你有没有什么问题想问&quot;。准备 2-3 个：</p><table tabindex="0"><thead><tr><th>类型</th><th>问题示例</th><th>用意</th></tr></thead><tbody><tr><td><strong>业务</strong></td><td>&quot;团队目前最在意的项目是哪几个？今年的产品规划是什么？&quot;</td><td>了解公司核心业务</td></tr><tr><td><strong>团队</strong></td><td>&quot;前端团队规模和分工？有没有跨端 / 基建方向的投入？&quot;</td><td>评估技术成长空间</td></tr><tr><td><strong>流程</strong></td><td>&quot;从需求到上线一般怎么走？前后端协作模式？&quot;</td><td>评估工程化水平</td></tr><tr><td><strong>成长</strong></td><td>&quot;组里有没有内部分享 / 沉淀机制？&quot;</td><td>评估学习氛围</td></tr></tbody></table><blockquote><p>⚠️ <strong>不要问</strong>：薪资（HR 面谈）、加班强度（终面议）、多面几家比较（显得不专注）</p></blockquote><h2 id="当前项目面试文档" tabindex="-1">当前项目面试文档 <a class="header-anchor" href="#当前项目面试文档" aria-label="Permalink to &quot;当前项目面试文档&quot;">​</a></h2><ul><li><a href="./项目经验/">项目面试经验总览</a></li><li><a href="./项目经验/01-商户管理SaaS平台">商户管理 SaaS 平台</a></li><li><a href="./项目经验/02-会员服务平台Web-H5">会员服务平台 Web / H5</a></li><li><a href="./项目经验/03-智能风控引擎平台">智能风控引擎平台</a></li><li><a href="./项目经验/04-农业数字化App-IoT大屏">农业数字化项目 App + IoT 大屏</a></li></ul>`,36)])])}const b=a(r,[["render",l]]);export{u as __pageData,b as default};
